94		for _, v := range opts.Volumes {
95			spec := strings.TrimSpace(v)
96			if source, ok := volumeSource(spec); ok {
97				if m, flagged := h.check(spec, source); flagged {
98					found = append(found, m)
99				}
100			}
101		}
102		for _, v := range opts.Mounts {
103			spec := strings.TrimSpace(v)
104			for _, source := range mountSources(spec) {
105				if m, flagged := h.check(spec, source); flagged {
106					found = append(found, m)
107					break
108				}
109			}
110		}
111		return found
112	}
113	
114	func volumeSource(spec string) (string, bool) {
115		source, _, ok := strings.Cut(spec, ":")
116		if !ok {
117			return "", false
118		}
119		source = strings.TrimSpace(source)
120		return source, isHostPath(source)
121	}
122	
123	// mountSources returns the host paths a --mount value binds. Keys and the value
124	// of type are read in any case. type=bind (and Podman's type=glob) binds its
125	// source (or src); type=volume, or no type, binds each volume-opt=device=<path>
126	// (the local driver's bind in disguise). The target (target, dst, destination)
127	// is the container's and never read.
128	func mountSources(spec string) []string {
129		var typ, source string
130		var devices []string
131		for tok := range strings.SplitSeq(spec, ",") {
132			key, value, ok := strings.Cut(strings.TrimSpace(tok), "=")
133			if !ok {
134				continue
135			}
136			value = strings.TrimSpace(value)
137			switch strings.ToLower(strings.TrimSpace(key)) {
138			case "type":
139				typ = strings.ToLower(value)
140			case "source", "src":
141				source = value
142			case "volume-opt":
143				if name, device, ok := strings.Cut(value, "="); ok && strings.EqualFold(strings.TrimSpace(name), "device") {
144					devices = append(devices, strings.TrimSpace(device))
145				}
146			}
147		}
148		var out []string
149		switch typ {
150		case "bind", "glob":
151			if isHostPath(source) {
152				out = append(out, source)
153			}
154		case "", "volume":
155			for _, d := range devices {
156				if isHostPath(d) {
157					out = append(out, d)
158				}
159			}
160		}
161		return out
162	}
163	
164	// isHostPath reports whether a bind source names a host path rather than a
165	// volume: a volume name starts with a letter or a digit, and the Docker CLI makes
166	// any source that starts with "." absolute.
167	func isHostPath(source string) bool {
168		return strings.HasPrefix(source, "/") || strings.HasPrefix(source, ".") || strings.HasPrefix(source, "~")
169	}
170	
171	// procHostRoot matches /proc/<pid>/root and /proc/<pid>/cwd (also self and
172	// thread-self) and what is under them: the root and the working directory of a
173	// process are reached through its /proc entry, and the root of PID 1 is the
174	// host's whatever the permissions say.
175	var procHostRoot = regexp.MustCompile(`^/proc/(?:[0-9]+|self|thread-self)/(?:root|cwd)(?:/|$)`)
176	
177	// mountTarget is a sensitive path and the category of what it holds.
178	type mountTarget struct {
179		path     string
180		category MountCategory
181	}
182	
183	// mountHost is what a classification reads from the machine, once per call.
184	type mountHost struct {
185		home    string          // HOME as set, for the expansion of "~"; "" when unset or not absolute
186		homes   []string        // the home of the user and its resolved form: HOME, or the user database when HOME is unusable
187		cwd     string          // working directory, "" when unreadable
188		etc     []string        // "/etc" and its resolved form
189		ssh     []string        // ~/.ssh as written and as resolved (it is often a link)
190		devdesk []string        // ~/.devdesk as written and as resolved
191		sockets map[string]bool // engine socket paths, as written and resolved
192		targets []mountTarget   // the sensitive paths an ancestor is flagged for, in order of precedence
193	}
194	
195	func newMountHost() mountHost {
196		h := mountHost{sockets: map[string]bool{}}
197		if home := os.Getenv("HOME"); path.IsAbs(home) {
198			h.home = path.Clean(home)
199		}
200		base := h.home
201		if base == "" {
202			base = fallbackHome()
203		}
204		if base != "" {
205			h.homes = withResolved(base)
206			for _, d := range h.homes {
207				h.ssh = appendMissing(h.ssh, withResolved(path.Join(d, ".ssh"))...)
208				h.devdesk = appendMissing(h.devdesk, withResolved(path.Join(d, ".devdesk"))...)
209			}
210		}
211		if cwd, err := os.Getwd(); err == nil && path.IsAbs(cwd) {
212			h.cwd = cwd
213		}
214		h.etc = withResolved("/etc")
215		for _, sock := range engineSockets() {
216			for _, p := range withResolved(sock) {
217				h.sockets[p] = true
218				h.targets = append(h.targets, mountTarget{p, MountEngineSocket})
219			}
220		}
221		for _, group := range []struct {
222			paths    []string
223			category MountCategory
224		}{
225			{h.etc, MountSystemConfig}, {h.homes, MountHome}, {h.ssh, MountSSH}, {h.devdesk, MountDevDesk},
226		} {
227			for _, p := range group.paths {
228				h.targets = append(h.targets, mountTarget{p, group.category})
229			}
230		}
231		return h
232	}
233	
234	// fallbackHome is the home of the user when HOME says nothing usable: the home
235	// directory of the environment, then the user database. It serves the home
236	// categories only; "~" is never expanded with it.
237	func fallbackHome() string {
238		if d, err := os.UserHomeDir(); err == nil && path.IsAbs(d) {
239			return path.Clean(d)
240		}
241		if u, err := user.Current(); err == nil && path.IsAbs(u.HomeDir) {
242			return path.Clean(u.HomeDir)
243		}
244		return ""
245	}
246	
247	// appendMissing appends each of add that dst does not hold yet.
248	func appendMissing(dst []string, add ...string) []string {
249		for _, a := range add {
250			if !slices.Contains(dst, a) {
251				dst = append(dst, a)
252			}
253		}
254		return dst
255	}
256	
257	// withResolved returns p cleaned and, when different, as far as its links resolve.
258	func withResolved(p string) []string {
259		out := []string{path.Clean(p)}
260		if r := resolvePath(p); r.path != out[0] {
261			out = append(out, r.path)
262		}
263		return out
264	}
265	
266	// engineSockets lists where a container engine listens: Docker, Podman and
267	// containerd at their usual places, under XDG_RUNTIME_DIR (or /run/user/<uid>
268	// when it is unset) for the rootless ones, and the unix socket of DOCKER_HOST or
269	// CONTAINER_HOST. A tcp:// or ssh:// host names no file.
270	func engineSockets() []string {
271		socks := []string{
272			"/var/run/docker.sock", "/run/docker.sock",
273			"/var/run/podman/podman.sock", "/run/podman/podman.sock",
274			"/run/containerd/containerd.sock",
275		}
276		xdg := os.Getenv("XDG_RUNTIME_DIR")
277		if !path.IsAbs(xdg) && os.Getuid() >= 0 {
278			xdg = "/run/user/" + strconv.Itoa(os.Getuid())
279		}
280		if path.IsAbs(xdg) {
281			socks = append(socks, path.Join(xdg, "docker.sock"), path.Join(xdg, "podman", "podman.sock"))
282		}
283		for _, name := range []string{"DOCKER_HOST", "CONTAINER_HOST"} {
284			if p, ok := strings.CutPrefix(os.Getenv(name), "unix://"); ok && path.IsAbs(p) {
285				socks = append(socks, p)
286			}
287		}
288		return socks
289	}
290	
291	// absolute returns the host path a source designates, before any resolution:
292	// "~" and "~/..." under HOME, a relative source under the working directory.
293	func (h mountHost) absolute(source string) (string, bool) {
294		switch {
295		case path.IsAbs(source):
296			return source, true
297		case source == "~" || strings.HasPrefix(source, "~/"):
298			if h.home == "" {
299				return "", false // nothing to expand it with: not read as anything
300			}
301			return h.home + strings.TrimPrefix(source, "~"), true
302		case h.cwd == "":
303			return "", false
304		}
305		return h.cwd + "/" + source, true
306	}
307	
308	// check classifies one bind source. The candidates are the paths it can lead to:
309	// for each reading of a ".." after a link (the link followed first, as the kernel
310	// does, and the path cleaned first, as the Docker CLI does) the path as resolved
311	// when it resolves in full, otherwise as written and then as resolved so far (a
312	// link into /etc followed by a name that does not exist yet is /etc's). The
313	// first candidate that is equal to or under a sensitive path wins, then the
314	// first that holds one, then a path that could not be read.
315	func (h mountHost) check(spec, source string) (SensitiveMount, bool) {
316		abs, ok := h.absolute(source)
317		if !ok {
318			return SensitiveMount{}, false
319		}
320		clean := path.Clean(abs)
321		flag := func(p string, cat MountCategory) (SensitiveMount, bool) {
322			return SensitiveMount{
323				Spec: spec, Source: source, Path: p, Category: cat,
324				Reason: mountReasons[cat], EngineSocket: cat == MountEngineSocket,
325			}, true
326		}
327		if procHostRoot.MatchString(clean) {
328			return flag(clean, MountRoot)
329		}
330		var candidates []string
331		unverified := false
332		for _, reading := range appendMissing(nil, abs, clean) {
333			r := resolvePath(reading)
334			unverified = unverified || r.unverified
335			if r.complete {
336				candidates = appendMissing(candidates, r.path)
337			} else {
338				candidates = appendMissing(candidates, path.Clean(reading), r.path)
339			}
340		}
341		for _, c := range candidates {
342			if cat, flagged := h.classify(c); flagged {
343				return flag(c, cat)
344			}
345		}
346		for _, c := range candidates {
347			if cat, flagged := h.holds(c); flagged {
348				return flag(c, cat)
349			}
350		}
351		if unverified {
352			return flag(clean, MountUnverified)
353		}
354		return SensitiveMount{}, false
355	}
356	
357	// classify returns the category of a resolved absolute path that is equal to or
358	// under a sensitive one, or is a socket file (any socket may be an engine's).
359	func (h mountHost) classify(p string) (MountCategory, bool) {
360		switch {
361		case h.sockets[p]:
362			return MountEngineSocket, true
363		case p == "/":
364			return MountRoot, true
365		case underAny(p, h.etc):
366			return MountSystemConfig, true
367		case underAny(p, h.ssh):
368			return MountSSH, true
369		case underAny(p, h.devdesk):
370			return MountDevDesk, true
371		case slices.Contains(h.homes, p):
372			return MountHome, true
373		}
374		if info, err := os.Stat(p); err == nil && info.Mode()&fs.ModeSocket != 0 {
375			return MountEngineSocket, true
376		}
377		return "", false
378	}
379	
380	// holds returns the category of the first sensitive path that p is an ancestor
381	// of: mounting /run hands over /run/docker.sock.
382	func (h mountHost) holds(p string) (MountCategory, bool) {
383		for _, t := range h.targets {
384			if strings.HasPrefix(t.path, p+"/") {
385				return t.category, true
386			}
387		}
388		return "", false
389	}
390	
391	// underAny reports whether p is equal to or under one of the bases. Whole
392	// components only: "/etcetera" is not under "/etc".
393	func underAny(p string, bases []string) bool {
394		for _, base := range bases {
395			if p == base || strings.HasPrefix(p, base+"/") {
396				return true
397			}
398		}
399		return false
400	}
401	
402	// resolution is what resolvePath found.
403	type resolution struct {
404		path       string // the path with its links followed as far as they could be
405		complete   bool   // every component exists
406		unverified bool   // a component could not be read for a reason other than "does not exist"
407	}
408	
409	// isMissing reports whether err says the path is not there (a component that
410	// does not exist, or a file where a directory was expected).
411	func isMissing(err error) bool {
412		return errors.Is(err, fs.ErrNotExist) || errors.Is(err, syscall.ENOTDIR)
413	}
414	
415	// resolvePath resolves an absolute path component by component, following each
416	// link where it stands, so that a ".." after a link applies to the link's target
417	// as the kernel does (a Clean first would apply it to the link's name). A
418	// component that does not exist or cannot be read is kept as written, and so is
419	// everything after it; the result says which of the two it was. Too many links
420	// (a loop) give the path cleaned as written, incomplete and not unverified.
421	func resolvePath(p string) resolution {
422		rest := pathComponents(p)
423		var cur []string
424		r := resolution{complete: true}
425		follows := 0
426		for len(rest) > 0 {
427			c := rest[0]
428			rest = rest[1:]
429			if c == ".." {
430				if len(cur) > 0 {
431					cur = cur[:len(cur)-1]
432				}
433				continue
434			}
435			if r.complete {
436				next := "/" + strings.Join(append(slices.Clone(cur), c), "/")
437				info, err := os.Lstat(next)
438				switch {
439				case err != nil:
440					r.complete, r.unverified = false, !isMissing(err)
441				case info.Mode()&os.ModeSymlink != 0:
442					follows++
443					if follows > maxLinkFollows {
444						return resolution{path: path.Clean(p)}
445					}
446					target, err := os.Readlink(next)
447					if err != nil {
448						r.complete, r.unverified = false, !isMissing(err)
449						break
450					}
451					if path.IsAbs(target) {
452						cur = nil
453					}
454					rest = append(pathComponents(target), rest...)
455					continue
456				}
457			}
458			cur = append(cur, c)
459		}
460		r.path = "/" + strings.Join(cur, "/")
461		return r
462	}
463	
464	// pathComponents splits p on "/" and drops the empty and "." components.
465	func pathComponents(p string) []string {
466		var out []string
467		for c := range strings.SplitSeq(p, "/") {
468			if c != "" && c != "." {
469				out = append(out, c)
470			}
471		}
472		return out
473	}
